        assertThat(applyReseal("alice", evidenceKey, uniqueKey("CMD"),
                uniqueKey("RS"), "SEAL-2", "bob").getResponse().getStatus()).isEqualTo(200);
        assertThat(applyReseal("alice", evidenceKey, uniqueKey("CMD"),
